import React, { useEffect, useState, useRef, useMemo } from "react";
import { toast } from "react-toastify";
import postService from "../../services/postService";
import uploadService from "../../services/uploadService";
import { resolveImageUrl } from "../../components/ProductCard";
import Loader from "../../components/Loader";

import ReactQuill from "react-quill";
import "react-quill/dist/quill.snow.css";

const emptyForm = { title: "", thumbnail: "", content: "", author: "", status: "PUBLISHED" };

export default function PostManagementPage() {
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyForm);
  const [saving, setSaving] = useState(false);
  const [uploading, setUploading] = useState(false);

  // Tạo một ref để thao tác trực tiếp với thực thể bộ soạn thảo Quill
  const quillRef = useRef(null);

  // --- HÀM TÙY BIẾN CHO PHÉP CHỌN VÀ UPLOAD ẢNH TỪ MÁY TÍNH VÀO NỘI DUNG ---
  const imageHandler = () => {
    const input = document.createElement("input");
    input.setAttribute("type", "file");
    input.setAttribute("accept", "image/*");
    input.click();

    input.onchange = async () => {
      const file = input.files?.[0];
      if (!file) return;

      try {
        const res = await uploadService.uploadImage(file);
        const imageUrl = res.data.url || res.data.fileName;
        const fullImageUrl = resolveImageUrl(imageUrl);

        // Chèn hình ảnh vào đúng vị trí con trỏ hiện tại trong khung văn bản
        const quill = quillRef.current.getEditor();
        const range = quill.getSelection();
        quill.insertEmbed(range.index, "image", fullImageUrl);
        quill.setSelection(range.index + 1);
      } catch (err) {
        console.error(err);
        toast.error("Không thể chèn hình ảnh local vào nội dung bài viết");
      }
    };
  };

  // --- BẢNG CẤU HÌNH ĐẦY ĐỦ TẤT CẢ CÁC TÍNH NĂNG TRÊN THANH CÔNG CỤ (TOOLBAR) ---
  const modules = useMemo(() => ({
    toolbar: {
      container: [
        [{ font: [] }, { size: [] }], // Chọn font chữ và cỡ chữ
        ["bold", "italic", "underline", "strike"], // Định dạng text cơ bản
        [{ color: [] }, { background: [] }], // Màu chữ (Text Color) và Màu nền chữ (Background Color)
        [{ script: "sub" }, { script: "super" }], // Chỉ số dưới, chỉ số trên
        [{ header: [1, 2, 3, 4, 5, 6, false] }], // Định dạng tiêu đề H1 -> H6
        [{ list: "ordered" }, { list: "bullet" }, { indent: "-1" }, { indent: "+1" }], // Danh sách, thụt lề
        [{ direction: "rtl" }, { align: [] }], // Hướng văn bản và căn lề (Trái, Giữa, Phải, Đều 2 bên)
        ["link", "image", "video"], // Chèn liên kết, hình ảnh local (đã custom), video URL
        ["clean"] // Nút xóa nhanh mọi định dạng đang áp dụng
      ],
      handlers: {
        image: imageHandler // Kích hoạt hàm xử lý chọn ảnh local thay vì điền link thô
      }
    }
  }), []);

  const formats = [
    "font", "size", "bold", "italic", "underline", "strike", "color", "background",
    "script", "header", "list", "bullet", "indent", "direction", "align", "link", "image", "video"
  ];

  const loadPosts = async () => {
    setLoading(true);
    try {
      const res = await postService.getAllAdmin();
      setPosts(res.data);
    } catch (err) {
      console.error("=== LỖI API BACKEND ===", err.response?.data);
      const errorMessage = err.response?.data?.message || err.response?.data?.error || "Lỗi 500 hệ thống";
      const errorTrace = err.response?.data?.trace ? err.response.data.trace.substring(0, 250) : "Không có trace log";
      alert(`❌ LỖI HỆ THỐNG (SPRING BOOT 500):\n\nNguyên nhân: ${errorMessage}\n\nChi tiết: ${errorTrace}`);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadPosts();
  }, []);

  const openCreate = () => {
    setEditingId(null);
    setForm(emptyForm);
    setShowModal(true);
  };

  const openEdit = (p) => {
    setEditingId(p.id);
    setForm({
      title: p.title,
      thumbnail: p.thumbnail || "",
      content: p.content || "",
      author: p.author || "",
      status: p.status,
    });
    setShowModal(true);
  };

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleContentChange = (htmlValue) => {
    setForm((prev) => ({ ...prev, content: htmlValue }));
  };

  const handleThumbnailSelect = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    try {
      const res = await uploadService.uploadImage(file);
      setForm((prev) => ({ ...prev, thumbnail: res.data.url }));
      toast.success("Đã tải ảnh lên thành công");
    } catch (err) {
      toast.error(err.response?.data?.message || "Không thể tải ảnh lên");
    } finally {
      setUploading(false);
      e.target.value = "";
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      if (editingId) {
        await postService.update(editingId, form);
        toast.success("Đã cập nhật bài viết");
      } else {
        await postService.create(form);
        toast.success("Đã đăng bài viết mới");
      }
      setShowModal(false);
      loadPosts();
    } catch (err) {
      toast.error(err.response?.data?.message || "Có lỗi xảy ra");
    } finally {
      setSaving(false);
    }
  };

  const handleToggleVisibility = async (id) => {
    try {
      await postService.toggleVisibility(id);
      loadPosts();
    } catch (err) {
      toast.error(err.response?.data?.message || "Không thể thay đổi trạng thái");
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Bạn có chắc muốn xóa bài viết này?")) return;
    try {
      await postService.delete(id);
      toast.success("Đã xóa bài viết");
      loadPosts();
    } catch (err) {
      toast.error(err.response?.data?.message || "Không thể xóa bài viết");
    }
  };

  return (
    <div>
      <div className="flex items-center justify-between mb-6">
        <h1 className="font-display text-2xl text-ink">Quản lý bài viết</h1>
        <button
          onClick={openCreate}
          className="bg-ember text-white text-sm font-semibold px-4 py-2 rounded-md hover:brightness-95"
        >
          + Thêm bài viết
        </button>
      </div>

      {loading ? (
        <Loader />
      ) : (
        <div className="bg-white border border-gray-200 rounded-xl overflow-hidden">
          <table className="w-full text-sm">
            <thead className="bg-gray-50 text-steel text-left">
              <tr>
                <th className="px-4 py-3">Bài viết</th>
                <th className="px-4 py-3">Tác giả</th>
                <th className="px-4 py-3">Ngày đăng</th>
                <th className="px-4 py-3">Trạng thái</th>
                <th className="px-4 py-3 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {posts.map((p) => (
                <tr key={p.id}>
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-3">
                      <img
                        src={resolveImageUrl(p.thumbnail) || "https://placehold.co/48x32?text=Post"}
                        alt=""
                        className="w-12 h-8 rounded-md object-cover shrink-0"
                      />
                      <span className="font-medium text-ink line-clamp-1">{p.title}</span>
                    </div>
                  </td>
                  <td className="px-4 py-3 text-steel">{p.author || "-"}</td>
                  <td className="px-4 py-3 text-steel">
                    {new Date(p.createdAt).toLocaleDateString("vi-VN")}
                  </td>
                  <td className="px-4 py-3">
                    <button
                      onClick={() => handleToggleVisibility(p.id)}
                      className={`text-xs font-semibold px-2 py-1 rounded-full ${
                        p.status === "PUBLISHED"
                          ? "bg-green-100 text-green-700"
                          : "bg-gray-200 text-steel"
                      }`}
                    >
                      {p.status === "PUBLISHED" ? "Đang hiện" : "Đang ẩn"}
                    </button>
                  </td>
                  <td className="px-4 py-3 text-right space-x-3">
                    <button onClick={() => openEdit(p)} className="text-blue-600 hover:underline">
                      Sửa
                    </button>
                    <button onClick={() => handleDelete(p.id)} className="text-red-500 hover:underline">
                      Xóa
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl w-full max-w-4xl max-h-[90vh] overflow-y-auto p-6">
            <h2 className="font-display text-xl text-ink mb-4">
              {editingId ? "Sửa bài viết" : "Thêm bài viết mới"}
            </h2>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-ink mb-1">Tiêu đề</label>
                <input
                  name="title"
                  value={form.title}
                  onChange={handleChange}
                  required
                  className="w-full border border-gray-300 rounded-md px-3 py-2 text-sm"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-ink mb-1">Ảnh đại diện bài viết</label>
                <div className="flex items-center gap-4">
                  <div className="w-24 h-16 rounded-md border border-gray-200 bg-gray-50 overflow-hidden shrink-0 flex items-center justify-center">
                    {form.thumbnail ? (
                      <img
                        src={resolveImageUrl(form.thumbnail)}
                        alt=""
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <span className="text-xs text-steel">Chưa có ảnh</span>
                    )}
                  </div>
                  <input
                    type="file"
                    accept="image/*"
                    onChange={handleThumbnailSelect}
                    disabled={uploading}
                    className="flex-1 text-sm text-steel file:mr-3 file:py-2 file:px-4 file:rounded-md file:border-0 file:text-sm file:font-semibold file:bg-ink file:text-white hover:file:bg-black file:cursor-pointer disabled:opacity-60"
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-ink mb-1">Tác giả</label>
                <input
                  name="author"
                  value={form.author}
                  onChange={handleChange}
                  placeholder="BikeShop Team"
                  className="w-full border border-gray-300 rounded-md px-3 py-2 text-sm"
                />
              </div>

              {/* Trình soạn thảo văn bản tích hợp đầy đủ mọi tính năng */}
              <div>
                <label className="block text-sm font-medium text-ink mb-2">Nội dung chi tiết bài viết</label>
                <div className="bg-white rounded-md border border-gray-300 overflow-hidden min-h-[420px]">
                  <ReactQuill
                    ref={quillRef}
                    theme="snow"
                    value={form.content}
                    onChange={handleContentChange}
                    modules={modules}
                    formats={formats}
                    placeholder="Hãy thiết kế bài viết chia sẻ kiến thức xe đạp tại đây..."
                    className="h-[350px] mb-12 border-none"
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-ink mb-1">Trạng thái</label>
                <select
                  name="status"
                  value={form.status}
                  onChange={handleChange}
                  className="w-full border border-gray-300 rounded-md px-3 py-2 text-sm"
                >
                  <option value="PUBLISHED">Hiển thị</option>
                  <option value="HIDDEN">Ẩn</option>
                </select>
              </div>

              <div className="flex justify-end gap-3 pt-2">
                <button
                  type="button"
                  onClick={() => setShowModal(false)}
                  className="px-4 py-2 text-sm font-medium text-steel hover:text-ink"
                >
                  Hủy
                </button>
                <button
                  type="submit"
                  disabled={saving || uploading}
                  className="bg-ember text-white text-sm font-semibold px-5 py-2 rounded-md hover:brightness-95 disabled:opacity-60"
                >
                  {saving ? "Đang lưu..." : "Lưu bài viết"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
